// Count initial ones
$ones = 0;
for ($i = 0; $i < $n; $i++) {
    if ($a[$i] == 1) $ones++;
}

// We need to find the best segment to flip.
// Flipping a segment [i, j] changes:
// - 1s in the segment become 0s (lose count)
// - 0s in the segment become 1s (gain count)
// Net change = (zeros in segment) - (ones in segment)
// We want to maximize: ones + net_change
// Equivalent to maximizing: (zeros - ones) over all segments
// Let's define value: for each element, if it's 0, flipping gives +1; if it's 1, flipping gives -1.
// So we want max subarray sum of array b where b[i] = (a[i]==0 ? 1 : -1)
// But we must do exactly one move, so we must pick at least one element.

// Use Kadane's algorithm to find max subarray sum
$maxSum = -1000000;
$currentSum = 0;
for ($i = 0; $i < $n; $i++) {
    $val = ($a[$i] == 0) ? 1 : -1;
    $currentSum += $val;
    if ($currentSum > $maxSum) {
        $maxSum = $currentSum;
    }
    if ($currentSum < 0) {
        $currentSum = 0;
    }
}

// The answer is ones + maxSum
echo $ones + $maxSum . "\n";
?>
