<?php
$n = (int)trim(fgets(STDIN));
$line = trim(fgets(STDIN));
$a = array_map('intval', explode(' ', $line));

// Count initial ones
$ones = count(array_filter($a, function($x) { return $x === 1; }));

// We need to find the maximum gain from flipping a contiguous subarray.
// Flipping a segment: 0s become 1s (gain +1 each), 1s become 0s (loss -1 each).
// So the net change for a segment is (number of 0s) - (number of 1s) in that segment.
// We want to maximize this net change, then add to initial ones.

// Convert: treat 0 as +1, 1 as -1, then find max subarray sum.
$transformed = array_map(function($x) { return $x === 0 ? 1 : -1; }, $a);

// Kadane's algorithm for max subarray sum
$maxEndingHere = 0;
$maxSoFar = 0;
for ($i = 0; $i < $n; $i++) {
    $maxEndingHere = max($transformed[$i], $maxEndingHere + $transformed[$i]);
    $maxSoFar = max($maxSoFar, $maxEndingHere);
}

$result = $ones + $maxSoFar;
echo $result . "\n";
?>
