// We need to find the maximum gain from flipping one contiguous segment.
// Flipping a segment changes 0s to 1s and 1s to 0s.
// The gain for a segment is: (number of 0s in segment) - (number of 1s in segment)
// We want to maximize this gain.
// This is equivalent to finding the maximum subarray sum where:
// - 0 contributes +1 (flipping 0 to 1 gains 1)
// - 1 contributes -1 (flipping 1 to 0 loses 1)

// Use Kadane's algorithm to find maximum subarray sum
$best = 0; // minimum gain could be negative, but we must flip exactly one segment
$current = 0;

// Actually, we must flip exactly one non-empty segment, so we need to track the best (possibly negative) gain
// But since we can choose any i <= j, the segment must be non-empty.

// Let's use Kadane's that allows negative values
$bestGain = PHP_INT_MIN;
$currentGain = 0;

for ($i = 0; $i < $n; $i++) {
    $val = ($a[$i] === 0) ? 1 : -1;
    if ($i === 0) {
        $currentGain = $val;
    } else {
        $currentGain = max($val, $currentGain + $val);
    }
    if ($currentGain > $bestGain) {
        $bestGain = $currentGain;
    }
}

$result = $ones + $bestGain;
echo $result . "\n";
